<template><label class="figma-checkbox"><input class="hidden" type="checkbox" :checked="modelValue" @change="emit('update:modelValue', $event.target.checked)" /><span class="box" :class="{ checked: modelValue }">{{ modelValue ? '✓' : '' }}</span><span><slot /></span></label></template>
<script setup>defineProps({ modelValue: Boolean }); const emit = defineEmits(['update:modelValue'])</script>
<style scoped>.figma-checkbox{min-height:22px;display:flex;align-items:center;gap:8px;color:#1D2129;font:400 14px/22px "PingFang SC",sans-serif;cursor:pointer}.hidden{position:absolute;width:1px;height:1px;opacity:0}.box{width:14px;height:14px;flex:0 0 14px;box-sizing:border-box;display:flex;align-items:center;justify-content:center;overflow:hidden;border:2px solid #E5E6EB;border-radius:2px;color:#fff;background:#fff;font-size:11px;font-weight:700;line-height:14px}.box.checked{border-color:#00AAA6;background:#00AAA6}.figma-checkbox>span:last-child{min-width:0;overflow:hidden;text-overflow:ellipsis;white-space:nowrap}</style>
